/**
 * Critical css: every page of views/html (except the ignored ones in utilities/critical.js) has its
 * file, generated by the current build, and the page inlines it
 */
import { existsSync, statSync } from "fs";
import { createResult } from "./results.js";

const item = "Critical CSS";

const criticalFolder = "public/css/critical";
const buildManifest = "public/build/manifest.json";

// <x-frontend::critical-css> with a critical: inline <style> plus the stylesheet preloaded
const inlinedCriticalPattern = /<link rel="preload" as="style"/;

export default async function checkCritical({ pages }) {
    const results = [];
    const buildTime = statSync(buildManifest).mtimeMs;

    // Real routes (extraUrls) aren't views/html pages: their critical css isn't generated
    for (const { name, url, template } of pages.filter(
        (page) => page.template,
    )) {
        const file = `${criticalFolder}/${template}_critical.min.css`;

        if (!existsSync(file) || statSync(file).size === 0) {
            results.push(
                createResult(item, name, "fail", [
                    `${file} não existe ou está vazio: rode \`npm run build\` com o app no ar`,
                ]),
            );
            continue;
        }

        const response = await fetch(url);
        const html = await response.text();
        const head = html.split("</head>")[0];

        if (!inlinedCriticalPattern.test(head)) {
            results.push(
                createResult(item, name, "fail", [
                    `a página não injeta o css crítico: confira o 'critical' => '${template}.css' da view`,
                ]),
            );
            continue;
        }

        // The critical is written a moment after the manifest: a minute of margin
        const isOutdated = statSync(file).mtimeMs < buildTime - 60_000;

        results.push(
            isOutdated
                ? createResult(item, name, "warn", [
                      `${file} é mais antigo que o último build: o app estava fora do ar no build?`,
                  ])
                : createResult(item, name, "pass"),
        );
    }

    return results;
}
